const defaultCompanion={tips:['Mach nach einem Kapitel eine kurze Pause. Dein Kopf braucht Zeit, damit Wissen Wurzeln schlägt.','Erkläre etwas Neues in deinen eigenen Worten. So merkst du, was du schon verstanden hast.','Über den Lernpfad kannst du jederzeit zu einem früheren Kapitel zurückspringen.','Ein kleiner Schritt für die Natur: Nutze deine Trinkflasche immer wieder.','Fragen sind wie Samen: Aus einer kleinen Frage kann eine grosse Entdeckung wachsen.'],interval:25};
function normalizeCompanion(c){return c&&Array.isArray(c.tips)&&c.tips.length?{tips:c.tips,interval:Number.isInteger(c.interval)&&c.interval>=10&&c.interval<=120?c.interval:25}:{tips:[...defaultCompanion.tips],interval:25}}
const initial={title:'Klima verstehen. Zukunft gestalten.',chapters:[{title:'Grundlagen',subtitle:'Unser Klima verstehen',content:'Wetter und Klima – was ist der Unterschied?\n\nDas Wetter beschreibt, wie die Atmosphäre an einem bestimmten Ort gerade ist: sonnig, regnerisch, warm oder kalt. Das Klima beschreibt dagegen die typischen Wetterverhältnisse über einen langen Zeitraum, meist mindestens 30 Jahre.\n\nDie Erde als Gewächshaus\n\nEin Teil der Sonnenstrahlung erwärmt die Erdoberfläche. Diese gibt Energie als Wärmestrahlung ab. Treibhausgase nehmen einen Teil dieser Strahlung auf und geben sie in alle Richtungen ab – auch zurück zur Erdoberfläche. Dieser natürliche Treibhauseffekt macht Leben auf der Erde möglich. Ohne ihn läge die globale Durchschnittstemperatur bei etwa −18 °C statt bei rund +15 °C.\n\nMerke dir: Ein kalter Tag widerlegt keine langfristige Erwärmung. Wetter ist eine Momentaufnahme, Klima ist das grosse Bild.',question:'Was beschreibt der Begriff Klima?',answers:['Das Wetter an einem einzelnen Tag','Typische Wetterverhältnisse über einen langen Zeitraum','Nur die Temperatur im Sommer'],correct:1,explanation:'Klima beschreibt die statistischen Eigenschaften des Wetters über einen langen Zeitraum, meist mindestens 30 Jahre.',minutes:6},{title:'Ursachen',subtitle:'Warum wird die Erde wärmer?',content:'Der Mensch verändert die Atmosphäre\n\nSeit Beginn der Industrialisierung verbrennen wir grosse Mengen Kohle, Erdöl und Erdgas. Dabei gelangt zusätzliches Kohlendioxid (CO₂) in die Atmosphäre. Gleichzeitig werden Wälder gerodet, die CO₂ aufnehmen könnten.\n\nMehr als nur CO₂\n\nAuch Methan trägt zur Erwärmung bei. Es entsteht unter anderem in der Tierhaltung und bei der Förderung fossiler Energieträger. Lachgas wird beispielsweise durch die landwirtschaftliche Nutzung von Böden freigesetzt.\n\nDer natürliche Treibhauseffekt wird dadurch verstärkt. Die Erde gibt weniger Energie ins Weltall ab, als sie von der Sonne aufnimmt – bis sich ein neues, wärmeres Gleichgewicht einstellt.',question:'Welche Tätigkeit setzt zusätzliches CO₂ frei?',answers:['Strom aus Sonnenenergie gewinnen','Bäume pflanzen','Kohle, Erdöl und Erdgas verbrennen'],correct:2,explanation:'Bei der Verbrennung fossiler Energieträger wird gebundener Kohlenstoff als CO₂ freigesetzt.',minutes:8},{title:'Folgen',subtitle:'Eine Welt im Wandel',content:'Die Veränderungen werden sichtbar\n\nGletscher verlieren an Masse. Der Meeresspiegel steigt, weil sich wärmeres Meerwasser ausdehnt und Eis auf dem Land schmilzt. Hitzewellen werden in vielen Regionen häufiger und intensiver.\n\nWasser im Ungleichgewicht\n\nWärmere Luft kann mehr Wasserdampf aufnehmen. Das kann Starkregen verstärken. Gleichzeitig können höhere Temperaturen die Verdunstung erhöhen und Trockenheit in manchen Regionen verschärfen.\n\nAuch bei uns\n\nIn den Alpen verändern schwindende Gletscher und tauender Permafrost die Landschaft. Für Menschen, Tiere und Pflanzen verändert sich der Lebensraum. Die Folgen unterscheiden sich je nach Region.',question:'Warum steigt der Meeresspiegel?',answers:['Wärmeres Meerwasser dehnt sich aus und Landeis schmilzt','Weil die Erde grösser wird','Nur weil es mehr regnet'],correct:0,explanation:'Die thermische Ausdehnung des Meerwassers und das Schmelzen von Landeis tragen zum Meeresspiegelanstieg bei.',minutes:7},{title:'Lösungen',subtitle:'Gemeinsam etwas bewegen',content:'Viele kleine und grosse Hebel\n\nKlimaschutz bedeutet, den Ausstoss von Treibhausgasen zu verringern. Dazu gehören erneuerbare Energien, gut gedämmte Gebäude, eine klimafreundlichere Mobilität und ein bewusster Umgang mit Ressourcen.\n\nDein Alltag zählt\n\nMit dem Velo oder öffentlichen Verkehr unterwegs sein, Lebensmittelverschwendung vermeiden und Dinge länger nutzen: Viele Entscheidungen können einen Unterschied machen. Welche Massnahme wie viel bewirkt, hängt von den Umständen ab.\n\nGemeinsam geht mehr\n\nAuch Schulen, Unternehmen und die Politik gestalten die Zukunft. Überlege: Welche Veränderung könntet ihr als Klasse anstossen? Plant eine konkrete Aktion und besprecht, wie ihr ihre Wirkung beurteilen könnt.',question:'Welche Massnahme hilft, Treibhausgasemissionen zu verringern?',answers:['Lebensmittel wegwerfen','Erneuerbare Energien ausbauen','Mehr Kohlekraftwerke bauen'],correct:1,explanation:'Erneuerbare Energien können fossile Energieträger ersetzen und so den Ausstoss von Treibhausgasen verringern.',minutes:6},{title:'Abschluss',subtitle:'Dein Wissen macht den Unterschied',content:'Das grosse Bild\n\nDu hast gelernt, wie sich Wetter und Klima unterscheiden, warum Treibhausgase wichtig sind und wie menschliche Aktivitäten die Erde erwärmen. Du kennst einige Folgen und Möglichkeiten zum Klimaschutz.\n\nDenke weiter\n\nErkläre einer anderen Person den Treibhauseffekt in deinen eigenen Worten. Welche Zusammenhänge fallen dir leicht? Wo möchtest du noch einmal nachlesen? Über den Lernpfad kannst du jedes Kapitel erneut öffnen.\n\nDeine nächste Idee\n\nNotiere eine Frage, die du noch zum Klimawandel hast. Suche gemeinsam mit deiner Lehrperson nach verlässlichen Quellen und vergleiche die Antworten.',question:'Warum ist der natürliche Treibhauseffekt wichtig?',answers:['Er verhindert jeden Wetterwechsel','Er macht die Erde kalt und unbewohnbar','Er hält die Erde warm genug für Leben'],correct:2,explanation:'Der natürliche Treibhauseffekt sorgt für eine lebensfreundliche Durchschnittstemperatur. Problematisch ist seine zusätzliche Verstärkung durch menschliche Emissionen.',minutes:4}]};
const KEY='lumio-learning-v1';
function validTopic(s,max=12){return s&&s.course&&typeof s.course.title==='string'&&s.course.title.trim().length>0&&Array.isArray(s.course.chapters)&&s.course.chapters.length>0&&s.course.chapters.length<=max&&s.course.chapters.every(c=>typeof c.title==='string'&&typeof c.subtitle==='string'&&typeof c.content==='string'&&typeof c.question==='string'&&Array.isArray(c.answers)&&c.answers.length===3&&c.answers.every(a=>typeof a==='string')&&Number.isInteger(c.correct)&&c.correct>=0&&c.correct<3&&typeof c.explanation==='string'&&(c.minutes===undefined||Number.isInteger(c.minutes)&&c.minutes>=1&&c.minutes<=120)&&(!c.image||/^data:image\/(png|jpeg|webp|gif);base64,/.test(c.image)))&&Array.isArray(s.done)&&new Set(s.done).size===s.done.length&&s.done.every(i=>Number.isInteger(i)&&i>=0&&i<s.course.chapters.length)&&Number.isInteger(s.current)&&s.current>=0&&s.current<s.course.chapters.length&&s.answers&&typeof s.answers==='object'&&!Array.isArray(s.answers)&&Object.entries(s.answers).every(([i,a])=>/^\d+$/.test(i)&&Number(i)<s.course.chapters.length&&Number.isInteger(a)&&a>=0&&a<3)}
function valid(s){if(!s||typeof s!=='object')return false;if(s.companion!==undefined&&(!s.companion||!Array.isArray(s.companion.tips)||s.companion.tips.length<1||s.companion.tips.length>30||!s.companion.tips.every(t=>typeof t==='string'&&t.trim().length>0&&t.length<=240)||!Number.isInteger(s.companion.interval)||s.companion.interval<10||s.companion.interval>120))return false;return s.topics!==undefined?Array.isArray(s.topics)&&s.topics.length>0&&s.topics.every(t=>validTopic(t))&&Number.isInteger(s.activeTopic)&&s.activeTopic>=0&&s.activeTopic<s.topics.length:validTopic(s,30)}
function normalizeState(data){
 let topics=data.topics,activeTopic=data.activeTopic;
 if(!topics){topics=[];for(let start=0;start<data.course.chapters.length;start+=12){const chapters=data.course.chapters.slice(start,start+12);topics.push({course:{...data.course,title:data.course.title+(start?' · Fortsetzung '+(Math.floor(start/12)+1):''),chapters},done:data.done.filter(i=>i>=start&&i<start+chapters.length).map(i=>i-start),current:Math.max(0,Math.min(chapters.length-1,data.current-start)),answers:Object.fromEntries(Object.entries(data.answers).filter(([i])=>Number(i)>=start&&Number(i)<start+chapters.length).map(([i,a])=>[Number(i)-start,a]))})}activeTopic=Math.floor(data.current/12)}
 const normalized={topics,activeTopic,companion:normalizeCompanion(data.companion)};
 // Active-topic aliases keep the lesson/editor code scoped to the selected topic.
 for(const key of ['course','done','current','answers'])Object.defineProperty(normalized,key,{get(){return this.topics[this.activeTopic][key]},set(value){this.topics[this.activeTopic][key]=value},configurable:true});
 return normalized;
}
const serverMode=!!window.__LUMIO_SERVER__;const sessionUser=window.__LUMIO_SERVER__?.user;let state=normalizeState(window.__LUMIO_SERVER__||{course:initial,done:[],current:0,answers:{}}),storageOK=true;
try{const saved=serverMode?null:JSON.parse(localStorage.getItem(KEY));if(saved&&valid(saved))state=normalizeState(saved)}catch(e){storageOK=false}
let view='home',editorIndex=0;
function topicSelector(){return `<section class="topic-selector glass"><div><span class="eyebrow">DEINE OBERBEGRIFFE</span><label for="active-topic">Wähle deinen Lernbereich</label></div><select id="active-topic" onchange="switchTopic(Number(this.value))">${state.topics.map((t,i)=>`<option value="${i}" ${state.activeTopic===i?'selected':''}>${esc(t.course.title)} · ${t.course.chapters.length}/12 Beiträge</option>`).join('')}</select><span class="topic-counter">${state.topics.length} ${state.topics.length===1?'Oberbegriff':'Oberbegriffe'}</span></section>`}
function switchTopic(index){if(!Number.isInteger(index)||!state.topics[index]||index===state.activeTopic)return;state.activeTopic=index;editorIndex=0;save();render()}
function newChapter(){return {title:'Neuer Beitrag',subtitle:'Dein nächster Aha-Moment',content:'Hier beginnt dein Lerninhalt.',question:'Was hast du gelernt?',answers:['Antwort A','Antwort B','Antwort C'],correct:0,explanation:'Ergänze hier deine Erklärung.',minutes:5}}
function addTopic(title){if(serverMode&&sessionUser.role!=='admin')return;title=String(title||'').trim();if(!title||title.length>100)return toast('Bitte einen Oberbegriff mit 1–100 Zeichen eingeben.');state.topics.push({course:{title,chapters:[newChapter()]},done:[],current:0,answers:{}});state.activeTopic=state.topics.length-1;editorIndex=0;save();render();toast('Oberbegriff angelegt. Du kannst bis zu 12 Beiträge erstellen.')}
function esc(t){return String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function save(){if(serverMode&&typeof scheduleServerSave==='function'){storageOK=false;return scheduleServerSave()}try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true}catch(e){storageOK=false;toast('Speichern nicht möglich. Bitte Daten exportieren.')}document.querySelector('.save-status').innerHTML='<i></i> '+(storageOK?'Lokal gespeichert':'Nicht gespeichert')}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}const percent=()=>Math.round(state.done.length/state.course.chapters.length*100);const resume=()=>{const i=state.course.chapters.findIndex((_,i)=>!state.done.includes(i));return i<0?0:i};
function navigate(v){if(serverMode&&['admin','access'].includes(v)&&sessionUser.role!=='admin')return toast('Dieser Bereich ist nur für Admins verfügbar.');view=v;if(v==='course'&&state.current===undefined)state.current=resume();render();window.scrollTo({top:0,behavior:'smooth'})}function openChapter(i){state.current=i;save();navigate('course')}
function path(){return `<div class="path glass" style="--steps:${state.course.chapters.length}">${state.course.chapters.map((c,i)=>`<button class="step ${state.done.includes(i)?'done':''} ${i===state.current?'current':''}" onclick="openChapter(${i})" ${i===state.current?'aria-current="step"':''}><span class="number">${state.done.includes(i)?'✓':String(i+1).padStart(2,'0')}</span><b>${esc(c.title)}</b><small>${state.done.includes(i)?'Abgeschlossen':i===state.current?'Du bist hier':`${c.minutes||5} Min.`}</small></button>`).join('')}</div>`}
function heading(k,title,text){return `<div class="intro"><span class="eyebrow">${k}</span><h1>${title}</h1><p>${text}</p></div>`}
function home(){const done=state.done.length;return `${heading('RAUM FÜR NEUGIER','Dein nächster Aha-Moment. <span>✧</span>','Schön, dass du da bist. Entdecke Neues – in deinem eigenen Tempo.')}<section class="hero"><div class="hero-content"><span class="badge"><i></i> DEINE LERNREISE IM GRÜNEN</span><h2>Wissen wächst.<br>Mit deiner Neugier.</h2><p>Ein Lernraum mitten in der Natur.<br>Entdecke, was unsere Welt bewegt.</p><button class="primary" onclick="openChapter(${resume()})">${done?'Weiterlernen':'Lernreise starten'} <span>↗</span></button><span class="hero-note">${state.course.chapters.length} Kapitel · ca. ${state.course.chapters.reduce((a,c)=>a+(Number(c.minutes)||5),0)} Minuten</span></div><div class="nature-seal" aria-hidden="true"><span>❧</span><small>WACHSEN<br>MIT WISSEN</small></div><span class="orb-caption">DEIN MOMENT IN DER NATUR</span></section><div class="stats"><div class="stat glass"><span class="stat-icon">◷</span><div><strong>${percent()} <small>%</small></strong><p>Dein Lernfortschritt</p></div></div><div class="stat glass"><span class="stat-icon">✓</span><div><strong>${done} <small>/ ${state.course.chapters.length}</small></strong><p>Kapitel abgeschlossen</p></div></div><div class="stat glass"><span class="stat-icon">✧</span><div><strong>${Object.keys(state.answers).filter(k=>state.answers[k]===state.course.chapters[k]?.correct).length}</strong><p>Wissenschecks gemeistert</p></div></div></div><div class="section-heading"><h2>Dein Lernpfad</h2><button class="text-button" onclick="navigate('course')">Alle Kapitel ansehen ↗</button></div>${path()}<div class="lower-grid"><section><div class="section-heading"><h2>Dein Kurs</h2><span class="eyebrow" style="font-size:8px">FÜR DICH ENTDECKT</span></div><button class="course-card glass" style="width:100%;text-align:left" onclick="openChapter(${resume()})"><div class="landscape" aria-hidden="true"><div class="sun"></div></div><div class="course-info"><span class="eyebrow">DEIN AKTUELLER OBERBEGRIFF</span><h3>${esc(state.course.title)}</h3><p>${state.course.chapters.length} Kapitel &nbsp; · &nbsp; Mit interaktiven Wissenschecks</p><div class="progress-label"><span>${done?'Deine Reise hat begonnen':'Dein erster Schritt wartet'}</span><span>${percent()} %</span></div><div class="progress"><div style="width:${percent()}%"></div></div></div></button></section><section><div class="section-heading"><h2>Ein Gedanke für dich</h2></div><div class="quote-card glass"><span class="quote-icon">❧</span><p>Wie ein Baum wächst auch dein Wissen.<br>Mit Zeit, Neugier und guten Wurzeln.</p><small>RAUM ZUM WACHSEN</small></div></section></div>`}
function course(){const i=state.current,c=state.course.chapters[i],checked=Object.hasOwn(state.answers,i),right=checked&&state.answers[i]===c.correct;return `${heading('DEIN LERNPFAD',esc(state.course.title),'Schritt für Schritt entdecken. Jederzeit zurückspringen und vertiefen.')}${path()}<div class="lesson-layout"><div><article class="lesson glass"><span class="eyebrow">KAPITEL ${String(i+1).padStart(2,'0')} &nbsp; / &nbsp; ${c.minutes||5} MINUTEN LESEZEIT</span><h2>${esc(c.subtitle)}</h2>${c.image?`<img class="lesson-image" src="${esc(c.image)}" alt="Illustration zu ${esc(c.title)}">`:`<div class="lesson-visual" aria-label="Sonne, Erde und Natur">☀ <span>→</span> ◉ <span>→</span> ♧</div>`}<div class="lesson-body">${esc(c.content)}</div><div class="lesson-actions"><button class="secondary" onclick="${i?'openChapter('+(i-1)+')':"navigate('home')"}">← ${i?'Vorheriges Kapitel':'Zur Übersicht'}</button><button class="secondary" onclick="document.getElementById('quiz').scrollIntoView({behavior:'smooth'})">Wissen testen ↓</button></div></article><section class="quiz glass" id="quiz"><span class="eyebrow">DEIN AHA-CHECK</span><h3>${esc(c.question)}</h3><form id="quiz-form">${c.answers.map((a,j)=>`<label class="choice"><input type="radio" name="answer" value="${j}" ${checked&&state.answers[i]===j?'checked':''} required>${esc(a)}</label>`).join('')}${checked?`<div class="feedback ${right?'':'wrong'}" role="status"><strong>${right?'✓ Genau richtig!':'Noch nicht ganz. Probiere es nochmals.'}</strong><br>${right?esc(c.explanation):'Lies den Inhalt bei Bedarf noch einmal und wähle eine andere Antwort.'}</div>`:''}<div class="lesson-actions"><button class="primary" type="submit">${right?'Erneut prüfen':'Antwort prüfen'} <span>↗</span></button>${right?`<button class="secondary" type="button" onclick="${i<state.course.chapters.length-1?'openChapter('+(i+1)+')':"navigate('home');toast('Geschafft! Du hast den Kurs durchgearbeitet.')"}">${i<state.course.chapters.length-1?'Nächstes Kapitel →':'Zur Kursübersicht ✓'}</button>`:''}</div></form></section></div><aside class="lesson-aside glass"><span class="eyebrow">DEINE ETAPPEN</span><h3>Ein klarer Weg.</h3>${state.course.chapters.map((c,j)=>`<button class="chapter-link ${i===j?'selected':''}" onclick="openChapter(${j})"><span>${state.done.includes(j)?'✓':String(j+1).padStart(2,'0')}</span>${esc(c.title)}</button>`).join('')}<p class="note">Du bestimmst das Tempo. Alle Kapitel sind jederzeit zugänglich.</p></aside></div>`}
function review(){const completed=state.done;return `${heading('WISSEN, DAS BLEIBT','Ein zweiter Blick. Ein tieferes Verständnis.','Wiederhole abgeschlossene Kapitel und festige dein Wissen.')}<div class="glass admin-card">${completed.length?completed.map(i=>`<button class="chapter-link" onclick="openChapter(${i})"><span>↻</span><div><strong>${esc(state.course.chapters[i].title)}</strong><br>${esc(state.course.chapters[i].subtitle)}</div><span style="margin-left:auto">↗</span></button>`).join(''):`<div class="empty"><span style="font-size:40px;color:#b29dca">↻</span><h2>Dein Wissen wächst mit dir.</h2><p>Schliesse deinen ersten Wissenscheck ab. Danach findest du das Kapitel hier zum Wiederholen.</p><button class="primary" onclick="openChapter(0)">Erstes Kapitel entdecken ↗</button></div>`}</div>`}
function admin(){const c=state.course.chapters[editorIndex];return `${heading('INHALTE VERWALTEN','Platz für dein Wissen.','Gestalte Lerninhalte und Wissenschecks. Änderungen werden für die freigegebenen Gruppen gespeichert.')}<div class="admin-grid"><aside class="admin-card glass"><h3>Beiträge im Oberbegriff</h3><p>${state.course.chapters.length} von 12 Beiträgen · Fortschritt separat je Oberbegriff</p>${state.course.chapters.map((c,i)=>`<button class="chapter-link ${editorIndex===i?'selected':''}" onclick="selectEditor(${i})"><span>${String(i+1).padStart(2,'0')}</span>${esc(c.title)}</button>`).join('')}<div class="toolbar"><button class="secondary" onclick="addChapter()" ${state.course.chapters.length>=12?'disabled':''}>+ Neuer Beitrag</button></div><form id="new-topic" class="topic-create"><label for="topic-title">Weiteren Oberbegriff anlegen</label><input id="topic-title" name="topicTitle" placeholder="z. B. Biodiversität" required maxlength="100"><button class="secondary" type="submit">+ Oberbegriff anlegen</button></form><p>Mit einem Export sicherst du alle Oberbegriffe, Beiträge und Fortschritte als Datei.</p><button class="secondary" onclick="exportData()">Daten exportieren ↓</button><label class="file-label">Daten importieren ↑<input id="import" type="file" accept="application/json"></label><p>Importierte Inhalte ersetzen die gemeinsamen Lerninhalte. Bestehende Gruppenfreigaben für diese Inhalte müssen danach erneut gesetzt werden.</p></aside><section class="admin-card glass"><form id="editor"><h3>Beitrag bearbeiten</h3><label for="course-title">Oberbegriff</label><input id="course-title" name="courseTitle" value="${esc(state.course.title)}" required maxlength="100"><label for="chapter-title">Name im Lernpfad</label><input id="chapter-title" name="title" value="${esc(c.title)}" required maxlength="30"><label for="subtitle">Überschrift</label><input id="subtitle" name="subtitle" value="${esc(c.subtitle)}" required maxlength="140"><label for="body">Lerninhalt</label><textarea id="body" name="content" required>${esc(c.content)}</textarea><p>Schreibe deinen Inhalt als Text. Absätze bleiben erhalten; HTML wird aus Sicherheitsgründen als Text angezeigt.</p><label for="minutes">Lesezeit in Minuten</label><input id="minutes" name="minutes" type="number" min="1" max="120" value="${c.minutes||5}" required><label for="image">Bild hinzufügen (PNG, JPG, WebP oder GIF, maximal 1 MB)</label><input id="image" type="file" accept="image/png,image/jpeg,image/webp,image/gif">${c.image?'<p>Ein Bild ist hinterlegt. <button type="button" class="text-button" onclick="removeImage()">Bild entfernen</button></p>':''}<h3 style="margin-top:35px">Wissenscheck</h3><label for="question">Frage</label><input id="question" name="question" value="${esc(c.question)}" required><label>Antworten · Wähle die richtige Antwort aus</label>${c.answers.map((a,j)=>`<div class="answer-edit"><input type="radio" name="correct" value="${j}" ${c.correct===j?'checked':''} required aria-label="Antwort ${j+1} als richtig markieren"><input name="answer${j}" value="${esc(a)}" required aria-label="Antwort ${j+1}"></div>`).join('')}<label for="explanation">Erklärung nach einer richtigen Antwort</label><textarea class="short" id="explanation" name="explanation" required>${esc(c.explanation)}</textarea><div class="lesson-actions"><button class="primary" type="submit">Änderungen speichern ✓</button><button class="secondary" type="button" onclick="openChapter(${editorIndex})">Kapitel ansehen ↗</button></div><p>Wenn du eine Frage oder Antwort änderst, wird der zugehörige Wissenscheck zurückgesetzt.</p></form></section></div>`}
function selectEditor(i){editorIndex=i;render()}function addChapter(){if(serverMode&&sessionUser.role!=='admin')return;if(state.course.chapters.length>=12)return toast('Dieser Oberbegriff enthält bereits 12 Beiträge. Lege einen weiteren Oberbegriff an.');state.course.chapters.push(newChapter());editorIndex=state.course.chapters.length-1;save();render()}function removeImage(){if(serverMode&&sessionUser.role!=='admin')return;delete state.course.chapters[editorIndex].image;save();render();toast('Bild entfernt')}
function exportData(){if(serverMode&&sessionUser.role!=='admin')return;const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='lumio-lernraum.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Deine Daten wurden exportiert.')}
function render(){if(!state.topics.length){document.querySelector('#content').innerHTML=heading('DEIN LERNRAUM','Noch kein Lernbereich freigegeben.','Dein Admin kann deiner Gruppe Oberbegriffe zuordnen. Lade die Seite nach einer Freigabe neu.');return}if(view==='access'&&typeof renderAccess==='function'){renderAccess();return}document.querySelector('#content').innerHTML=topicSelector()+({home,course,review,admin}[view]||home)();document.querySelector('#breadcrumb').textContent=({home:'Übersicht',course:'Mein Lernpfad',review:'Wiederholen',admin:'Inhalte verwalten'})[view];document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===view));document.querySelector('.nav small').textContent=state.course.chapters.length;document.querySelector('.save-status').innerHTML='<i></i> '+(storageOK?'Lokal gespeichert':'Nicht gespeichert');const q=document.querySelector('#quiz-form');if(q)q.onsubmit=async e=>{e.preventDefault();const a=Number(new FormData(q).get('answer'));if(serverMode){await submitServerQuiz(a);return;}state.answers[state.current]=a;if(a===state.course.chapters[state.current].correct&&!state.done.includes(state.current))state.done.push(state.current);save();const y=window.scrollY;render();window.scrollTo(0,y)};const topicForm=document.querySelector('#new-topic');if(topicForm)topicForm.onsubmit=e=>{e.preventDefault();addTopic(new FormData(topicForm).get('topicTitle'))};const form=document.querySelector('#editor');if(typeof mountCompanionEditor==='function')mountCompanionEditor();if(typeof syncMiloTask==='function')syncMiloTask();if(form)form.onsubmit=async e=>{e.preventDefault();const submittedTopic=state.activeTopic,submittedIndex=editorIndex;const f=new FormData(form),old=state.course.chapters[editorIndex],file=document.querySelector('#image').files[0];let image=old.image;if(file){if(file.size>1024*1024)return toast('Das Bild ist zu gross. Bitte maximal 1 MB.');if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))return toast('Bitte ein unterstütztes Bildformat wählen.');image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}if(state.activeTopic!==submittedTopic||editorIndex!==submittedIndex)return toast('Der Lernbereich wurde gewechselt. Bitte den Beitrag erneut öffnen und speichern.');const updated={title:f.get('title').trim(),subtitle:f.get('subtitle').trim(),content:f.get('content').trim(),question:f.get('question').trim(),answers:[0,1,2].map(j=>f.get('answer'+j).trim()),correct:Number(f.get('correct')),explanation:f.get('explanation').trim(),minutes:Number(f.get('minutes')),...(image?{image}:{})};if(!updated.title||!updated.subtitle||!updated.content||!updated.question||updated.answers.some(a=>!a)||!updated.explanation||!f.get('courseTitle').trim())return toast('Bitte alle Felder ausfüllen.');if(old.question!==updated.question||old.correct!==updated.correct||JSON.stringify(old.answers)!==JSON.stringify(updated.answers)){delete state.answers[editorIndex];state.done=state.done.filter(i=>i!==editorIndex)}state.course.title=f.get('courseTitle').trim();state.course.chapters[editorIndex]=updated;save();if(storageOK)toast('Deine Änderungen sind gespeichert.');render()};const imp=document.querySelector('#import');if(imp)imp.onchange=async()=>{if(serverMode&&sessionUser.role!=='admin')return;const file=imp.files[0];if(!file)return;if(file.size>6*1024*1024)return toast('Die Datei ist zu gross (maximal 6 MB).');try{const data=JSON.parse(await file.text());if(!valid(data))throw Error();if(!confirm('Alle Oberbegriffe, Beiträge und Fortschritte in diesem Browser durch die importierten Daten ersetzen?'))return;state=normalizeState(data);if(serverMode)state.topics.forEach(t=>delete t.id);editorIndex=0;save();render();if(typeof refreshCompanion==='function')refreshCompanion();toast('Dein Lernraum wurde importiert.')}catch(e){toast('Diese Datei enthält keine gültigen Lumio-Daten.')}}}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));document.querySelector('.brand').onclick=e=>{e.preventDefault();navigate('home')};document.querySelector('#help').onclick=()=>document.querySelector('#info').showModal();document.querySelector('#info .close').onclick=()=>document.querySelector('#info').close();render();
